// Stands in for Telegram's sendMessage. The message itself is in this execution's input.
const b = $json.body || {};
return [{ json: { ok: true, result: { message_id: Date.now() % 1e9, date: Math.floor(Date.now() / 1000), chat: { id: b.chat_id }, text: b.text } } }];

// Stands in for GET graph.facebook.com/{version}/{lead id or form id}.
// Lead details are derived from the id, so the same lead id always returns the same family.
const id = String($json.params.id || '');
const fields = String($json.query.fields || '');
if (!fields.includes('field_data')) {   // form lookup: fields=name,locale
  const ar = id.endsWith('2');
  return [{ json: { id, name: ar ? 'نموذج التسجيل 2026' : 'Admissions enquiry 2026', locale: ar ? 'ar_AR' : 'en_US' } }];
}
let seed = (Number(id.slice(-9)) || 0) % 2147483646 + 1;
const rnd = () => (seed = (seed * 48271) % 2147483647) / 2147483647;
const pick = (a) => a[Math.floor(rnd() * a.length)];
const ar = rnd() < 0.5;
const name = ar
  ? pick(['ليلى', 'أحمد', 'فاطمة', 'خالد', 'مريم', 'يوسف']) + ' ' + pick(['العامري', 'الحمادي', 'المنصوري', 'الشامسي'])
  : pick(['Sarah', 'James', 'Priya', 'Omar', 'Emma', 'Daniel']) + ' ' + pick(['Khan', 'Smith', 'Fernandes', 'Haddad', 'Wilson']);
const [campaign, adset, ad] = pick([
  ['Admissions 2026 - Arabic', 'Parents Abu Dhabi 25-45', 'Video - principal welcome'],
  ['Admissions 2026 - English', 'Expat parents Dubai', 'Carousel - campus tour'],
  ['Open day October', 'Lookalike enquirers', 'Image - open day'],
]);
return [{ json: {
  id,
  created_time: new Date().toISOString().replace(/\.\d+Z$/, '+0000'),
  field_data: [
    { name: 'full_name', values: [name] },
    { name: 'phone_number', values: ['+97150' + String(Math.floor(rnd() * 1e7)).padStart(7, '0')] },
    { name: 'email', values: ['parent' + id.slice(-6) + '@example.com'] },
    { name: 'which_grade_is_your_child_applying_for?', values: [pick(['FS1', 'FS2', 'Year 1', 'Year 3', 'Year 7'])] },
  ],
  form_id: ar ? '200000000000002' : '200000000000001',
  ad_id: '300000000000003', ad_name: ad, adset_id: '310000000000001', adset_name: adset,
  campaign_id: '320000000000001', campaign_name: campaign,
  is_organic: false, platform: pick(['fb', 'ig']),
} }];

// Stands in for Bigin "create contact". The id comes from the phone/email, so a family keeps its id.
const c = ($json.body && $json.body.data && $json.body.data[0]) || {};
let h = 7;
for (const ch of String(c.Mobile || c.Email || c.Last_Name || '')) h = (h * 31 + ch.charCodeAt(0)) >>> 0;
return [{ json: { data: [{ code: 'SUCCESS', status: 'success', message: 'record added',
  details: { id: '6' + String(h).padStart(18, '0'), Created_Time: new Date().toISOString() } }] } }];

// Stands in for Bigin "add note to contact".
return [{ json: { data: [{ code: 'SUCCESS', status: 'success', message: 'record added',
  details: { id: '7' + String(Date.now()).padStart(18, '0'), Parent_Id: { id: $json.params.id } } }] } }];
